'use strict';
const L=window.UE_LISTS,C=window.UE_CONFIG,$=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const configured=!!(C.supabaseUrl&&C.supabasePublishableKey),demoKey='ue-energy-demo-v2';
let directory=[],tickets=[],profiles=[],profile=null,session=null,page='overview',filter={search:'',status:'',priority:'',assignee:'',overdue:false},selected=null,working=false;
const finished=t=>['Resolved','Closed','Cancelled'].includes(t.status),date=d=>d?new Date(d.length===10?d+'T12:00:00':d).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Not set',today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Banjul'}),overdue=t=>!finished(t)&&!!t.due&&t.due<today(),initials=n=>n.split(' ').map(p=>p[0]).slice(0,2).join(''),manager=()=>!configured||['admin','manager','dispatcher'].includes(profile?.role),canEdit=t=>manager()||profile?.name===t.assignee;
function toast(message){const activeDialog=document.querySelector('dialog[open]');if(activeDialog){let feedback=activeDialog.querySelector('.dialog-feedback');if(!feedback){feedback=document.createElement('p');feedback.className='dialog-feedback';feedback.setAttribute('role','status');activeDialog.prepend(feedback)}feedback.textContent=message;feedback.scrollIntoView({block:'nearest'})}$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,6500)}
function options(values,selectedValue='',blank=''){return (blank?`<option value="">${esc(blank)}</option>`:'')+values.map(v=>`<option value="${esc(v)}" ${v===selectedValue?'selected':''}>${esc(v)}</option>`).join('')}
function staff(includeHistorical=false){const rows=configured?profiles.map(p=>({name:p.name,role:p.role})):L.staff;if(includeHistorical){for(const t of tickets)if(t.assignee&&!rows.some(p=>p.name===t.assignee))rows.push({name:t.assignee,role:'Historical assignee · account not yet added'})}return rows}
function statusTag(s){let cls=s==='Open'?'open':s==='Escalated'?'escalated':s.includes('Pending')||s.includes('Parts')?'waiting':['Resolved','Closed'].includes(s)?'resolved':s==='In Progress'||s==='Assigned'?'progress':'';return `<span class="tag ${cls}">${esc(s)}</span>`}
function offset(days){let d=new Date();d.setDate(d.getDate()+days);return d.toLocaleDateString('en-CA',{timeZone:'Africa/Banjul'})}
function seed(){const rows=[['Inverter shuts down under load','Demo · Coastal Lodge','Kololi','Inverter','Critical','In Progress','Demo Technician A',-1],['Battery backup needs assessment','Demo · Riverside Office','Banjul','Battery Bank','High','Assigned','Demo Technician B',0],['Replace damaged solar connectors','Demo · Greenfield Farm','Brikama','Solar System','Medium','Pending Parts','Demo Technician C',2],['Generator preventive maintenance','Demo · Harbour Stores','Bakau','Generator','Medium','Open','',3],['Streetlight circuit inspection','Demo · West Coast Estate','Bijilo','Streetlight','Low','Resolved - Pending Confirmation','Demo Technician D',1],['New site load assessment','Demo · Community Centre','Lamin','Load Assessment','Medium','Assigned','Demo Technician A',4],['Changeover switch fault','Demo · Palm Guesthouse','Kotu','Changeover / ATS','High','Escalated','Demo Technician B',-2],['Solar panel cleaning completed','Demo · Valley School','Serrekunda','Preventive Maintenance','Low','Closed','Demo Technician C',-3]];return rows.map((r,i)=>({id:crypto.randomUUID(),number:`UE-TKT-${today().replaceAll('-','').slice(2)}-${String(i+1).padStart(4,'0')}`,title:r[0],customer:r[1],phone:'',location:r[2],category:r[3],priority:r[4],status:r[5],assignee:r[6],due:r[7]===null?'':offset(r[7]),team:'Technical',channel:'Call',description:'Fictional example for workflow review. No real customer information is included.',resolution:r[5]==='Closed'?'Inspection and service completed. Customer confirmed operation.':'',satisfaction:r[5]==='Closed'?'Satisfied':'Not Yet Confirmed',materials:[],events:[{at:new Date(Date.now()-(i+1)*3600000).toISOString(),actor:'Demo dispatcher',type:'Internal Follow-up',note:i===0?'Site inspection booked. Technician to check the load and inverter error history.':'Request logged and scheduled for follow-up.'}],created_at:new Date(Date.now()-(i+1)*86400000).toISOString(),version:1}))}
async function request(path,{method='GET',body,auth=true}={},retry=true){const res=await fetch(C.supabaseUrl+path,{method,headers:{apikey:C.supabasePublishableKey,'Content-Type':'application/json',...(auth&&session?{Authorization:'Bearer '+session.access_token}:{})},...(body?{body:JSON.stringify(body)}:{})});const data=await res.json().catch(()=>null);if(res.status===401&&session?.refresh_token&&retry){const r=await request('/auth/v1/token?grant_type=refresh_token',{method:'POST',auth:false,body:{refresh_token:session.refresh_token}},false);session=r;sessionStorage.setItem('ue-session',JSON.stringify(r));return request(path,{method,body,auth},false)}if(!res.ok)throw Error(data?.message||data?.error_description||data?.error||`Request failed (${res.status})`);return data}
async function loadShared(){const results=await Promise.all([request('/rest/v1/profiles?select=id,name,role,active&active=eq.true&order=name'),request('/rest/v1/tickets?select=*&order=created_at.desc'),request('/rest/v1/staff_directory?select=*&order=name'),request('/rest/v1/reference_lists?select=key,items')]);profiles=results[0];directory=results[2];for(const list of results[3])L[list.key]=list.items;profile=profiles.find(p=>p.id===session.user.id);if(!profile)throw Error('Your account is not an active staff member. Ask the administrator to add your profile.');tickets=results[1].map(r=>({...r.data,id:r.id,number:r.number,version:r.version,created_at:r.created_at,events:r.events,legacy_source:r.legacy_source||null}));}
async function saveTicket(data,note,type){if(configured){const row=await request('/rest/v1/rpc/save_ticket',{method:'POST',body:{p_id:data.id,p_expected_version:data.version||0,p_data:payload(data),p_note:note,p_type:type}});await loadShared();return row.id}else{const item={...data,version:(data.version||0)+1};item.events=[...(tickets.find(t=>t.id===data.id)?.events||[]),{at:new Date().toISOString(),actor:'Demo operator',type,note}];const list=tickets.filter(t=>t.id!==data.id);list.unshift(item);localStorage.setItem(demoKey,JSON.stringify(list));tickets=list;return data.id}}
function payload(t){const {id,number,version,created_at,events,legacy_source,...data}=t;return data}
async function run(task){if(working)return;working=true;document.querySelectorAll('dialog button[type="submit"]').forEach(b=>b.disabled=true);try{await task()}catch(e){toast(e.message)}finally{working=false;document.querySelectorAll('dialog button[type="submit"]').forEach(b=>b.disabled=false)}}
function filtered(){return tickets.filter(t=>(!filter.search||[t.number,t.title,t.customer,t.location].join(' ').toLowerCase().includes(filter.search.toLowerCase()))&&(!filter.status||t.status===filter.status)&&(!filter.priority||t.priority===filter.priority)&&(!filter.assignee||(filter.assignee==='__unassigned'?!t.assignee:t.assignee===filter.assignee))&&(!filter.overdue||overdue(t)))}
function table(rows,compact=false){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Ticket / customer</th><th>Status</th><th>Priority</th>${compact?'':'<th>Assigned to</th>'}<th>Due / follow-up</th></tr></thead><tbody>${rows.map(t=>`<tr data-ticket="${esc(t.id)}" tabindex="0" role="button" aria-label="Open ${esc(t.number)}"><td><div class="ticket-title">${esc(t.title)}</div><div class="ticket-sub">${esc(t.number)} · ${esc(t.customer)}</div></td><td>${statusTag(t.status)}</td><td><span class="priority ${esc(t.priority)}">${esc(t.priority)}</span></td>${compact?'':`<td>${esc(t.assignee||'Unassigned')}</td>`}<td class="${overdue(t)?'overdue':''}">${date(t.due)}${overdue(t)?'<div class="ticket-sub overdue">Overdue</div>':''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No tickets here yet. Create a ticket or adjust your filters.</div>'}
function stats(){const active=tickets.filter(t=>!finished(t)),done=tickets.filter(t=>['Resolved','Closed'].includes(t.status));return `<div class="stats">${[['Active tickets',active.length,'Across all service teams','▤'],['In progress',tickets.filter(t=>t.status==='In Progress').length,'Work currently underway','↗'],['Overdue tickets',tickets.filter(overdue).length,'Requests needing attention','◷'],['Resolved & closed',done.length,'Completed service requests','✓']].map(([label,n,sub,symbol])=>`<div class="stat"><div class="stat-label">${label}</div><span class="stat-symbol">${symbol}</span><div class="stat-value">${n}</div><div class="stat-foot">${sub}</div></div>`).join('')}</div>`}
function queue(){const values=[['Open',tickets.filter(t=>t.status==='Open').length],['In progress',tickets.filter(t=>['Assigned','In Progress'].includes(t.status)).length],['Waiting',tickets.filter(t=>t.status.startsWith('Pending')).length],['Confirmation',tickets.filter(t=>t.status==='Resolved - Pending Confirmation').length]];return values.map(([name,n])=>`<div class="queue-row"><div class="queue-line"><span>${name}</span><strong>${n}</strong></div><div class="bar"><i style="width:${Math.max(0,n/Math.max(1,tickets.length)*100)}%"></i></div></div>`).join('')}
function render(){page=location.hash.slice(1)||'overview';if(!['overview','tickets','team','materials','reports','tech','manager','ticket-report','lists','access'].includes(page))page='overview';const labels={tech:['Tech','Record the work on site.','Activities, timing, completion and technical notes.'],manager:['Manager','Keep every customer informed.','Record customer contact, next actions and manager decisions.'],'ticket-report':['Ticket report','The full story of a service request.','A printable report from the ticket, technical history and customer updates.'],lists:['Lists','Your operations reference lists.','The original workbook directory and standard service selections.'],access:['Team access','Only your approved Energy team.','Invite named colleagues, choose their role and revoke access when they leave.'],overview:['Overview','A clear view of every request.','Track the work. Support your team. Keep customers informed.'],tickets:['All tickets','Every request, in one place.','From first contact to customer confirmation.'],team:['Team workload','The right person for every job.','See ownership and balance active work across the team.'],materials:['Material catalogue','The parts behind the service.','Standard material names and units from your operations lists.'],reports:['Reports & backup','Turn service activity into insight.','Review performance and keep a portable copy of your work.']};$('#breadcrumb').textContent=labels[page][0];$('#page-title').textContent=labels[page][1];$('#page-description').textContent=labels[page][2];document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#access-nav').hidden=configured&&profile?.role!=='admin';$('#nav-count').textContent=tickets.filter(t=>!finished(t)).length;$('#new-ticket').hidden=configured&&!manager();$('#connect').hidden=!!profile;$('#logout').hidden=!profile;$('#mode').textContent=configured?(profile?'SHARED · STAFF WORKSPACE':'STAFF SIGN-IN REQUIRED'):'DEMO · THIS BROWSER ONLY';$('#identity').innerHTML=profile?`${esc(profile.name)}<small>${esc(profile.role)}</small>`:'Management preview<small>Local demo workspace</small>';$('#notice').textContent=configured?(profile?'Shared workspace · ticket updates are saved to your operations database. Refresh to load changes made by colleagues.':'This workspace uses staff sign-in. Sign in to view tickets; no customer records are loaded publicly.'):'You’re exploring a demo with fictional tickets. Changes stay in this browser and are not shared. Connect Supabase before using real customer data.';$('#save-state').textContent=configured?(profile?'Connected to Supabase':'Awaiting staff sign-in'):'Saved in this browser';
if(configured&&!profile){$('#content').innerHTML='<div class="panel panel-body"><h2>Welcome to your service desk.</h2><p class="section-note">Sign in with your invited Unique Energy staff account to manage customer requests. For access, contact your operations administrator. You can also explore the separate demo with fictional tickets.</p><a href="demo.html"><button>Explore the demo →</button></a></div>';return}
if(page==='overview'){const recent=[...tickets].sort((a,b)=>new Date(b.events.at(-1)?.at||b.created_at)-new Date(a.events.at(-1)?.at||a.created_at));const events=tickets.flatMap(t=>(t.events||[]).map(e=>({...e,number:t.number}))).sort((a,b)=>new Date(b.at)-new Date(a.at)).slice(0,4);$('#content').innerHTML=stats()+`<div class="overview-grid"><div><section class="panel"><div class="panel-head"><div><h2>Latest service requests</h2><p>A live picture of your service desk</p></div><a href="#tickets" class="text-button">View all tickets ↗</a></div>${table(recent.slice(0,6),true)}</section><section class="panel"><div class="panel-head"><div><h2>Recent activity</h2><p>Updates from across your operations</p></div><span class="tag">${configured?'Shared history':'Demo history'}</span></div><div class="panel-body">${events.map(e=>`<div class="activity"><span class="dot"></span><div><p><strong>${esc(e.number)}</strong> · ${esc(e.note)}</p><small>${esc(e.actor)} · ${date(e.at)}</small></div></div>`).join('')||'<p class="section-note">Activity will appear when your team creates or updates tickets.</p>'}</div></section></div><div class="overview-aside"><section class="panel"><div class="panel-head"><div><h2>Service pipeline</h2><p>Where requests stand</p></div><span>↗</span></div><div class="panel-body">${queue()}<p class="section-note">Includes open, active, waiting and confirmation stages.</p></div></section><section class="panel attention panel-body"><div class="eyebrow">NEEDS YOUR ATTENTION</div><h2>${tickets.filter(overdue).length} overdue tickets</h2><p>Stay ahead of delays. Review the next step, reach out to the customer, and update the follow-up date.</p><button id="overdue-shortcut">Review overdue tickets →</button></section></div></div>`;$('#overdue-shortcut').onclick=()=>{filter.overdue=true;location.hash='tickets'}}
if(page==='tickets'){$('#content').innerHTML=`<section class="panel"><div class="filters"><input id="search" type="search" placeholder="Search ticket, customer or location…" aria-label="Search tickets" value="${esc(filter.search)}"><select id="filter-status" aria-label="Filter status">${options(L.statuses,filter.status,'All statuses')}</select><select id="filter-priority" aria-label="Filter priority">${options(L.priorities,filter.priority,'All priorities')}</select><select id="filter-assignee" aria-label="Filter assignee">${options(['__unassigned',...staff(true).map(p=>p.name)],filter.assignee,'All assignees').replace('>__unassigned<','>Unassigned<')}</select><button id="filter-overdue" aria-pressed="${filter.overdue}" class="${filter.overdue?'primary':''}">Overdue</button><button id="clear-filters">Reset</button></div><div id="ticket-results">${table(filtered())}<div class="result-count">${filtered().length} tickets match your filters</div></div></section>`;$('#search').oninput=e=>{filter.search=e.target.value;updateTable()};for(const k of ['status','priority','assignee'])$('#filter-'+k).onchange=e=>{filter[k]=e.target.value;updateTable()};$('#filter-overdue').onclick=()=>{filter.overdue=!filter.overdue;render()};$('#clear-filters').onclick=()=>{filter={search:'',status:'',priority:'',assignee:'',overdue:false};render()}}
if(page==='team'){$('#content').innerHTML=`<p class="section-note">${tickets.filter(t=>!finished(t)&&!t.assignee).length} active requests are unassigned. Historical assignees retain their original work. A historical name does not grant sign-in access; accounts must be added separately.</p><div class="team-grid">${staff(true).map(p=>{const rows=tickets.filter(t=>t.assignee===p.name&&!finished(t));return `<div class="team-card"><span class="avatar">${esc(initials(p.name))}</span><h3>${esc(p.name)}</h3><p>${esc(p.role)}</p><strong>${rows.length}</strong> <span class="section-note">active tickets</span><div class="bar"><i style="width:${rows.length/Math.max(1,...staff(true).map(s=>tickets.filter(t=>t.assignee===s.name&&!finished(t)).length))*100}%"></i></div><p>${rows.filter(overdue).length} overdue tickets</p><button class="text-button" data-person="${esc(p.name)}">View tickets →</button></div>`}).join('')}</div>`;document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{filter={search:'',status:'',priority:'',overdue:false,assignee:b.dataset.person};location.hash='tickets'})}
if(page==='materials'){$('#content').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Standard material catalogue</h2><p>${L.materials.length} items · record usage on individual tickets</p></div><span class="tag">Operations master list</span></div><div class="filters"><input type="search" id="material-search" aria-label="Search materials" placeholder="Find a material…"></div><div id="material-results"></div></section>`;const draw=q=>{$('#material-results').innerHTML='<div class="table-wrap"><table><thead><tr><th>Material item</th><th>Default unit</th></tr></thead><tbody>'+L.materials.filter(m=>m.name.toLowerCase().includes(q.toLowerCase())).map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.unit)}</td></tr>`).join('')+'</tbody></table></div>'};draw('');$('#material-search').oninput=e=>draw(e.target.value)}
if(page==='reports'){$('#content').innerHTML=stats()+`<div class="report-grid"><section class="panel"><div class="panel-head"><h2>Tickets by service category</h2></div><div class="panel-body">${L.categories.map(cat=>[cat,tickets.filter(t=>t.category===cat).length]).filter(x=>x[1]).map(([c,n])=>`<div class="queue-row"><div class="queue-line"><span>${esc(c)}</span><strong>${n}</strong></div><div class="bar"><i style="width:${n/Math.max(1,tickets.length)*100}%"></i></div></div>`).join('')||'<p>No tickets yet.</p>'}</div></section><section class="panel panel-body"><h2>Export & continuity</h2><p>Download a CSV for management reporting, or a complete JSON export including work notes and material usage. Exports contain customer information: store them with your company’s protected files.</p><button id="export-csv">↓ Export ticket CSV</button><button id="export-json">↓ Full JSON export</button><button id="print-report">Print report</button><p>New follow-up dates are set by dispatch. Imported tickets retain their original SLA target as the initial due date, where available. Exact source timestamps and unavailable dates are shown on each imported ticket.</p>${configured?'<p>Production backups and recovery are managed through Supabase. JSON exports support later migration to your server.</p>':'<p>Demo storage is limited to this browser. Resetting restores fictional examples and removes demo edits.</p><button id="reset-demo">Reset demo data</button>'}</section></div>`;$('#export-csv').onclick=exportCSV;$('#export-json').onclick=()=>download('unique-tickets-'+today()+'.json',JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),tickets},null,2),'application/json');$('#print-report').onclick=()=>window.print();if($('#reset-demo'))$('#reset-demo').onclick=()=>{if(confirm('Replace all local demo tickets with the original fictional examples?')){const rows=seed();localStorage.setItem(demoKey,JSON.stringify(rows));tickets=rows;render();toast('Demo data reset.')}}}
if(['tech','manager','ticket-report','lists','access'].includes(page))renderEnergyPage();wireRows()}

function legacyDetails(t){const l=t.legacy_source;if(!l)return '';const source=l.ticket||{};return `<section class="legacy-record"><div class="eyebrow">CONTINUED FROM ORIGINAL WORKBOOK</div><h3>${esc(source['Service Request No.']||t.number)}</h3><p class="section-note">Original assignment: ${esc(source['Technician/ Assignee'])}. ${!profiles.some(p=>p.name===t.assignee)&&configured?'The assignee account has not been added yet.':''}</p><div class="info-label">Original created / SLA target</div><div class="info">${esc(source['Created Date/Time']||'Not recorded')} / ${esc(source['SLA Target Date/Time']||'Not recorded')}</div><div class="info-label">Invoice / original contact</div><div class="info">${esc(source['Invoice No.']||'Not recorded')}<br>${esc(source['Phone/Email']||'Not recorded')}</div><div class="info-label">Original internal notes</div><div class="info">${esc(source['Internal Notes']||'None recorded')}</div><div class="source-issues"><strong>Source details to review</strong><ul>${(l.issues||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><details><summary>View all original ticket and activity fields</summary><pre>${esc(JSON.stringify({ticket:source,activities:l.activities},null,2))}</pre></details><p class="section-note">Imported ${date(l.imported_at)} from ${esc(l.workbook)} · ${esc(l.source_sheet)} row ${esc(l.source_row)}. Original fields are retained separately from later updates.</p></section>`}

function wireRows(){document.querySelectorAll('[data-ticket]').forEach(row=>{row.onclick=()=>openDetail(row.dataset.ticket);row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openDetail(row.dataset.ticket)}}})}
function updateTable(){$('#ticket-results').innerHTML=table(filtered())+`<div class="result-count">${filtered().length} tickets match your filters</div>`;wireRows()}
function openDetail(id){document.querySelector('#detail-dialog .dialog-feedback')?.remove();selected=id;const t=tickets.find(t=>t.id===id);if(!t)return;const edit=canEdit(t);$('#detail-content').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">${esc(t.number)}</div><h2>${esc(t.title)}</h2>${statusTag(t.status)} <span class="priority ${esc(t.priority)}">${esc(t.priority)}</span></div><button data-close="detail-dialog" aria-label="Close">×</button></div><div class="detail-grid"><div><div class="info-label">Customer & site</div><div class="info">${esc(t.customer)}<br>${esc(t.location)}${t.phone?'<br>'+esc(t.phone):''}</div><div class="info-label">Request details</div><div class="info">${esc(t.description)}</div><div class="info-label">Service</div><div class="info">${esc(t.category)} · ${esc(t.team)}<br>First contact: ${esc(t.channel)}</div>${legacyDetails(t)}<h3>Activity history</h3><div class="timeline">${[...(t.events||[])].reverse().map(e=>`<article><small>${date(e.at)} · ${esc(e.actor)} · ${esc(e.type)}</small><p>${esc(e.note)}</p></article>`).join('')}</div>${edit?`<form id="note-form"><label>Record a work / customer update<select name="type">${options(L.updateTypes,'Internal Follow-up')}</select></label><label>Work activity<select name="activity">${options(L.activities,'Troubleshooting')}</select></label><label>Completion<select name="completion">${options(L.completion,'In Progress')}</select></label><label>Update details<textarea name="note" required rows="3" maxlength="6000" placeholder="What was done, what changed, and what happens next?"></textarea></label><button type="submit" class="primary">Add update</button></form>`:''}<h3>Materials used</h3>${t.materials.map(m=>`<div class="material-used">${esc(m.name)} <strong>× ${esc(m.qty)} ${esc(m.unit)}</strong></div>`).join('')||'<p class="section-note">No materials recorded.</p>'}${edit?`<form id="material-form"><div class="material-row"><select name="material" aria-label="Material">${options(L.materials.map(m=>m.name))}</select><input name="qty" type="number" min="0.01" max="100000" step="0.01" value="1" required aria-label="Quantity"><button type="submit">Add</button></div></form>`:''}</div><div><form id="update-form"><label>Status<select name="status" ${edit?'':'disabled'}>${options(manager()?L.statuses:L.statuses.filter(s=>!['Closed','Cancelled'].includes(s)||s===t.status),t.status)}</select></label><label>Assigned to<select name="assignee" ${manager()?'':'disabled'}>${options([...new Set([...staff().map(p=>p.name),...(t.assignee?[t.assignee]:[])])],t.assignee,'Unassigned')}</select></label><label>Priority<select name="priority" ${manager()?'':'disabled'}>${options(L.priorities,t.priority)}</select></label><label>Due / follow-up date<input name="due" type="date" value="${esc(t.due)}" ${t.legacy_source&&!t.due?'':'required'} ${edit?'':'disabled'}></label><label>Resolution summary<textarea name="resolution" rows="3" maxlength="6000" ${edit?'':'disabled'}>${esc(t.resolution||'')}</textarea></label><label>Customer satisfaction<select name="satisfaction" ${edit?'':'disabled'}>${options(L.satisfaction,t.satisfaction)}</select></label><p class="section-note">Resolution requires a summary. Closure requires customer feedback or a recorded “No Response” outcome. Only dispatchers and managers can close tickets.</p>${edit?'<button type="submit" class="primary">Save changes</button>':'<p class="section-note">You can view this ticket. Updates are limited to its assigned technician and managers.</p>'}</form></div></div>`;wireClose();if(!$('#detail-dialog').open)$('#detail-dialog').showModal();
if($('#note-form'))$('#note-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(async()=>{await saveTicket(t,`${f.get('activity')} · ${f.get('completion')}: ${f.get('note').trim()}`,f.get('type'));render();openDetail(id);toast('Update recorded.')})};
if($('#material-form'))$('#material-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),m=L.materials.find(x=>x.name===f.get('material')),qty=Number(f.get('qty'));run(async()=>{if(!Number.isFinite(qty)||qty<=0)throw Error('Enter a positive quantity.');await saveTicket({...t,materials:[...t.materials,{...m,qty}]},`Material used: ${m.name} × ${qty} ${m.unit}`,'Internal Follow-up');render();openDetail(id);toast('Material usage recorded.')})};
$('#update-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(async()=>{const next={...t,status:f.get('status'),assignee:manager()?f.get('assignee'):t.assignee,priority:manager()?f.get('priority'):t.priority,due:f.get('due'),resolution:f.get('resolution').trim(),satisfaction:f.get('satisfaction')};if(['Resolved - Pending Confirmation','Resolved','Closed'].includes(next.status)&&!next.resolution)throw Error('Add a resolution summary before resolving or closing.');if(next.status==='Closed'&&next.satisfaction==='Not Yet Confirmed')throw Error('Record customer feedback or No Response before closure.');if(next.status==='Assigned'&&!next.assignee)throw Error('Select a technician before marking Assigned.');const changes=['status','assignee','priority','due','resolution','satisfaction'].filter(k=>next[k]!==t[k]).map(k=>`${k}: ${next[k]||'not set'}`);if(!changes.length)return toast('No changes to save.');await saveTicket(next,changes.join('; '),'Internal Follow-up');render();openDetail(id);toast('Ticket updated.')})}}
function wireClose(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close())}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(){const cols=['number','title','customer','phone','location','category','team','status','priority','assignee','due','resolution','satisfaction','created_at'];const cell=v=>'"'+String(/^[=+\-@\t\r]/.test(String(v??'').trimStart())?"'"+v:v??'').replaceAll('"','""')+'"';download('unique-tickets-'+today()+'.csv','\uFEFF'+[cols.join(','),...tickets.map(t=>cols.map(k=>cell(t[k])).join(','))].join('\r\n'),'text/csv;charset=utf-8')}
$('#new-ticket').onclick=()=>{if(configured&&!profile)return $('#login-dialog').showModal();$('#category').innerHTML=options(L.categories);$('#priority').innerHTML=options(L.priorities,'Medium');$('#team').innerHTML=options(L.teams,'Technical');$('#assignee').innerHTML=options(staff().map(p=>p.name),'','Unassigned');$('#channel').innerHTML=options(L.updateTypes,'Call');$('#ticket-form').reset();$('#priority').value='Medium';$('#ticket-form [name="due"]').value=offset(1);$('#ticket-dialog').showModal()};
$('#ticket-form').onsubmit=e=>{e.preventDefault();const form=e.target;run(async()=>{const f=Object.fromEntries(new FormData(form));for(const k of ['title','customer','location','description']){f[k]=f[k].trim();if(!f[k])throw Error('Please complete all required fields.')}const id=crypto.randomUUID();await saveTicket({...f,id,number:'UE-TKT-'+today().replaceAll('-','').slice(2)+'-'+id.slice(0,8).toUpperCase(),status:f.assignee?'Assigned':'Open',resolution:'',satisfaction:'Not Yet Confirmed',materials:[],created_at:new Date().toISOString(),version:0},'Ticket created. '+f.description,'Internal Follow-up');form.reset();$('#ticket-dialog').close();location.hash='tickets';render();toast('Ticket created.')})};
$('#connect').onclick=()=>{$('#login-message').textContent=configured?'':'Supabase is not configured. Add the project URL and publishable key in config.js, then run database/schema.sql. This demo has no real sign-in.';$('#login-dialog').showModal()};
$('#login-form').onsubmit=e=>{e.preventDefault();run(async()=>{if(!configured)throw Error('Connect Supabase before signing in.');const f=Object.fromEntries(new FormData(e.target));session=await request('/auth/v1/token?grant_type=password',{method:'POST',auth:false,body:f});try{await loadShared();sessionStorage.setItem('ue-session',JSON.stringify(session));$('#login-dialog').close();e.target.reset();render();toast('Signed in.')}catch(err){session=null;profile=null;tickets=[];profiles=[];directory=[];sessionStorage.removeItem('ue-session');render();throw err}})};
$('#logout').onclick=()=>run(async()=>{try{await request('/auth/v1/logout',{method:'POST'})}finally{session=null;profile=null;tickets=[];profiles=[];directory=[];sessionStorage.removeItem('ue-session');render()}});
window.addEventListener('hashchange',render);wireClose();
(async()=>{try{const authHash=new URLSearchParams(location.hash.slice(1));if(configured&&authHash.has('access_token')){session={access_token:authHash.get('access_token'),refresh_token:authHash.get('refresh_token')};history.replaceState(null,'',location.pathname+location.search);const user=await request('/auth/v1/user');session.user=user;sessionStorage.setItem('ue-session',JSON.stringify(session));if(['invite','recovery'].includes(authHash.get('type')))$('#password-dialog').showModal();}if(configured){const stored=sessionStorage.getItem('ue-session');if(stored){session=JSON.parse(stored);await loadShared()}}else{const saved=localStorage.getItem(demoKey);tickets=saved?JSON.parse(saved):seed();if(!saved)localStorage.setItem(demoKey,JSON.stringify(tickets))}}catch(e){profile=null;session=null;tickets=[];sessionStorage.removeItem('ue-session');toast('Workspace could not load: '+e.message)}render()})();

$('#forgot-password').onclick=()=>run(async()=>{if(!configured)throw Error('Connect Supabase first.');const email=$('#login-form [name="email"]').value;if(!email)throw Error('Enter your staff email address first.');await request('/auth/v1/recover',{method:'POST',auth:false,body:{email},},false);toast('If the account exists, a password reset email has been requested.');});
$('#password-form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);if(f.get('password')!==f.get('confirm'))throw Error('Passwords must match.');await request('/auth/v1/user',{method:'PUT',body:{password:f.get('password')}});$('#password-dialog').close();e.target.reset();try{await loadShared();render();toast('Password saved. Welcome to the service desk.');}catch(err){toast('Password saved. Ask your administrator to activate your staff profile.');}})};

var energyChosen;
function renderEnergyPage(){energyChosen??={};const box=$('#content');
 if(page==='access'){if(!configured){box.innerHTML='<section class="panel panel-body"><h2>Administrator access only</h2><p class="section-note">In the shared workspace, approved Energy administrators can invite people by exact email, set roles and deactivate members. Demo names do not grant access.</p></section>';return}if(profile?.role!=='admin'){box.innerHTML='<div class="panel panel-body">Only an approved Energy administrator can manage membership.</div>';return}box.innerHTML=`<div class="report-grid"><section class="panel panel-body"><h2>Prepare an Energy team member</h2><p class="section-note">Add only a colleague who belongs to the Energy team. Save a draft now. No email is sent and no access is granted until the batch is released after Operations approval.</p><form id="member-invite"><label>Full name<input name="name" required maxlength="120"></label><label>Staff email<input name="email" type="email" required maxlength="254"></label><label>Access role<select name="role">${options(['technician','dispatcher','manager','admin'],'technician')}</select></label><p class="section-note">Technicians update assigned work. Dispatchers and managers manage tickets and customer updates. Administrators also control team access.</p><button type="submit" class="primary">Save pending invitation</button></form><p id="member-result" role="status"></p></section><section class="panel panel-body"><h2>Access rules</h2><p>Only invited, approved, active Energy members can read shared records. Being listed in the old workbook directory does not create a login.</p><p>Deactivation blocks new database requests immediately. An open workspace checks membership again on focus and every minute. Information already viewed or exported cannot be recalled.</p><p>Only administrators can grant or revoke membership. You cannot remove your own administrator access.</p></section></div><section class="panel"><div class="panel-head"><h2>Approved members</h2><button id="refresh-members">Refresh</button></div><div id="members-table" class="panel-body">Loading…</div></section>`;
 $('#member-invite').onsubmit=e=>{e.preventDefault();run(async()=>{const f=Object.fromEntries(new FormData(e.target));await request('/rest/v1/rpc/energy_stage_invitation',{method:'POST',body:{p_email:f.email,p_name:f.name,p_role:f.role,p_notes:'Added by administrator',p_included:true}});$('#member-result').textContent='Saved on hold. No invitation sent or access granted.';e.target.reset();await loadInvitationQueue()})};$('#refresh-members').onclick=()=>run(loadEnergyMembers);box.insertAdjacentHTML('afterbegin','<section class="panel panel-body"><h2>Pending team invitations</h2><div id="invitation-queue">Loading…</div></section>');run(async()=>{await loadInvitationQueue();await loadEnergyMembers()});return}
 if(page==='lists'){const sourceDirectory=configured?directory:L.staff.map(p=>({...p,source_role:p.role,source_active:true,email:'Demo directory — no account'}));box.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>${configured?'Original staff directory':'Example staff directory'}</h2><p>${sourceDirectory.length} directory entries · membership is approved separately in Team access</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Workbook role</th><th>Source active?</th><th>Notes</th></tr></thead><tbody>${sourceDirectory.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.email)}</td><td>${esc(p.source_role)}</td><td>${p.source_active?'Yes':'No'}</td><td>${esc(p.notes||'')}</td></tr>`).join('')}</tbody></table></div></section><div class="team-grid">${[['Statuses','statuses'],['Update types','updateTypes'],['Yes / No','yesNo'],['Satisfaction','satisfaction'],['Priorities','priorities'],['Service categories','categories'],['Teams','teams'],['Activity types','activities'],['Completion','completion'],['Units','units']].map(([label,key])=>`<section class="team-card"><h3>${label} <span class="tag">${L[key]?.length||0}</span></h3>${(L[key]||[]).map(v=>`<p>${esc(v)}</p>`).join('')}</section>`).join('')}<section class="team-card"><h3>Ticket selection (auto)</h3>${tickets.map(t=>`<p>${esc(t.number)}</p>`).join('')||'<p>No tickets yet.</p>'}</section></div><a href="#materials"><button>Open all ${L.materials.length} material items →</button></a>`;return}
 if(page==='manager'&&!manager()){box.innerHTML='<section class="panel panel-body">Customer-update controls are available to dispatchers, managers and administrators. Your assigned work is available in Tech.</section>';return}
 const rows=page==='tech'?tickets.filter(canEdit):tickets;
 const chosen=rows.find(t=>t.id===energyChosen[page])||rows[0];
 box.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>${page==='tech'?'Technical activity':page==='manager'?'Customer updates & manager control':'Service ticket report'}</h2><p>Select a ticket to continue its record</p></div></div><div class="panel-body"><label>Ticket<select id="energy-ticket">${rows.map(t=>`<option value="${esc(t.id)}" ${chosen?.id===t.id?'selected':''}>${esc(t.number)} · ${esc(t.customer)} · ${esc(t.status)}</option>`).join('')}</select></label><div id="energy-work-area"></div></div></section>`;$('#energy-ticket').onchange=e=>{energyChosen[page]=e.target.value;renderEnergyPage()};if(!chosen){$('#energy-work-area').innerHTML='<p class="section-note">No available tickets. A dispatcher can create and assign a request.</p>';return}energyChosen[page]=chosen.id;
 const t=chosen,src=t.legacy_source?.ticket||{},area=$('#energy-work-area');
 if(page==='ticket-report'){area.innerHTML=`<div class="ticket-print"><div class="eyebrow">UNIQUE ENERGY · SERVICE TICKET REPORT</div><h2>${esc(t.number)} · ${esc(t.title)}</h2><p>${statusTag(t.status)} <span class="priority ${esc(t.priority)}">${esc(t.priority)}</span></p><div class="report-grid"><div><div class="info-label">Customer / contact / site</div><div class="info">${esc(t.customer)}<br>${esc(src['Phone/Email']||t.phone||'Not recorded')}<br>${esc(t.location)}</div><div class="info-label">Service request / invoice</div><div class="info">${esc(src['Service Request No.']||'Not recorded')} / ${esc(src['Invoice No.']||'Not recorded')}</div></div><div><div class="info-label">Assigned to / team / category</div><div class="info">${esc(t.assignee||'Unassigned')}<br>${esc(t.team)} / ${esc(t.category)}</div><div class="info-label">Created / due / source SLA</div><div class="info">${date(t.created_at)} / ${date(t.due)} / ${esc(src['SLA Target Date/Time']||'Not recorded')}</div></div></div><h3>Work request & problem</h3><div class="info">${esc(t.title)}<br>${esc(t.description)}</div><h3>Resolution & customer feedback</h3><div class="info">${esc(t.resolution||'Not resolved')}<br>${esc(t.satisfaction)}</div><h3>Technical and customer activity history</h3><div class="timeline">${(t.events||[]).map(e=>`<article><small>${date(e.at)} · ${esc(e.actor)} · ${esc(e.type)}</small><p>${esc(e.note)}</p></article>`).join('')}</div><h3>Materials used</h3>${t.materials.map(m=>`<p>${esc(m.name)} × ${esc(m.qty)} ${esc(m.unit)}</p>`).join('')||'<p>No recorded material usage.</p>'}${legacyDetails(t)}</div><button id="print-ticket">Print / save PDF</button><button id="open-report-ticket">Open ticket</button>`;$('#print-ticket').onclick=()=>window.print();$('#open-report-ticket').onclick=()=>openDetail(t.id);return}
 const tech=page==='tech';area.innerHTML=`<div class="notice">${esc(t.title)} · ${esc(t.location)} · ${esc(t.assignee||'Unassigned')} · ${esc(t.status)}</div><form id="energy-work-form"><div class="form-grid">${tech?`<label>Time started<input name="started" type="datetime-local"></label><label>Time completed<input name="completed" type="datetime-local"></label><label>Activity type<select name="activity">${options(L.activities,'Inspection')}</select></label><label>Completion status<select name="completion">${options(L.completion,'In Progress')}</select></label><label>Vehicle number<input name="vehicle" maxlength="80"></label><label>Status update<select name="status">${options(manager()?L.statuses:L.statuses.filter(s=>!['Closed','Cancelled'].includes(s)||s===t.status),t.status)}</select></label><label class="full">Action taken<textarea name="action" required maxlength="3000" rows="3"></textarea></label><label class="full">Technician notes<textarea name="notes" maxlength="3000" rows="3"></textarea></label>`:`<label>Update type<select name="type">${options(L.updateTypes,'Call')}</select></label><label>Customer contact<input name="contact" maxlength="180" value="${esc(t.phone)}"></label><label>Follow-up required?<select name="followup">${options(L.yesNo||['Yes','No'],'Yes')}</select></label><label>Next follow-up date<input name="due" type="date" value="${esc(t.due)}"></label><label>Escalation required?<select name="escalation">${options(L.yesNo||['Yes','No'],'No')}</select></label><label>Customer satisfaction<select name="satisfaction">${options(L.satisfaction,t.satisfaction)}</select></label><label>Status / manager override<select name="status">${options(L.statuses,t.status)}</select></label><label>Resolution summary<textarea name="resolution" maxlength="3000">${esc(t.resolution)}</textarea></label><label class="full">Customer update notes<textarea name="notes" required maxlength="3000" rows="3"></textarea></label><label class="full">Next action<input name="nextAction" required maxlength="1000"></label><label class="full">Manager notes<textarea name="managerNotes" maxlength="2000"></textarea></label>`}</div><button type="submit" class="primary">${tech?'Record technical activity':'Record customer update'}</button> <button type="button" id="open-work-ticket">Open ticket & materials</button></form>`;$('#open-work-ticket').onclick=()=>openDetail(t.id);
 const history=t.events.filter(e=>tech?(e.type?.toLowerCase().includes('technical')||e.note.startsWith('TECHNICAL ACTIVITY')):(e.note.startsWith('CUSTOMER / MANAGER UPDATE')||['Call','WhatsApp','Email','Site Visit'].includes(e.type)));area.insertAdjacentHTML('beforeend',`<section class="workflow-history"><h3>${tech?'Technical activity history':'Contact and manager history'}</h3><div class="timeline">${history.map(e=>`<article><small>${date(e.at)} · ${esc(e.actor)} · ${esc(e.type)}</small><p>${esc(e.note)}</p></article>`).join('')||'<p class="section-note">No saved updates in this register yet.</p>'}</div></section>`);
 $('#energy-work-form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=Object.fromEntries(new FormData(e.target));let next={...t},note,type;if(tech){if(f.completed&&!f.started)throw Error('Record a start time before a completion time.');if(f.started&&f.completed&&new Date(f.completed)<new Date(f.started))throw Error('Completion must be after the start time.');next.status=f.status;if(['Resolved','Resolved - Pending Confirmation','Closed'].includes(next.status)&&(next.status!==t.status||!t.resolution))next.resolution=f.action.trim();note=`TECHNICAL ACTIVITY ${'UE-ACT-'+today().replaceAll('-','').slice(2)+'-'+crypto.randomUUID().slice(0,8).toUpperCase()}\nActivity: ${f.activity}\nCompletion: ${f.completion}\nStarted: ${f.started||'Not recorded'}\nCompleted: ${f.completed||'Not recorded'}\nVehicle: ${f.vehicle||'Not recorded'}\nAction taken: ${f.action}\nTechnician notes: ${f.notes}`;type='Internal Follow-up'}else{next.status=f.escalation==='Yes'?'Escalated':f.status;next.satisfaction=f.satisfaction;next.resolution=f.resolution.trim();if(f.followup==='Yes'&&!f.due)throw Error('Set the next follow-up date.');if(f.due)next.due=f.due;note=`CUSTOMER / MANAGER UPDATE ${'UE-UPD-'+today().replaceAll('-','').slice(2)+'-'+crypto.randomUUID().slice(0,8).toUpperCase()}\nContact: ${f.contact}\nFollow-up required: ${f.followup}\nNext follow-up: ${f.due||'Not recorded'}\nEscalation required: ${f.escalation}\nCustomer satisfaction: ${f.satisfaction}\nUpdate: ${f.notes}\nNext action: ${f.nextAction}\nManager notes: ${f.managerNotes}`;type=f.type}if(['Resolved','Resolved - Pending Confirmation','Closed'].includes(next.status)&&!next.resolution)throw Error('A resolution summary is required.');if(next.status==='Closed'&&next.satisfaction==='Not Yet Confirmed')throw Error('Record customer feedback or No Response before closure.');await saveTicket(next,note,type);render();toast(tech?'Technical activity recorded.':'Customer update recorded.')})};
}
async function loadEnergyMembers(){const rows=await request('/rest/v1/rpc/list_energy_members',{method:'POST',body:{}});if(!$('#members-table'))return;$('#members-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Member</th><th>Role</th><th>Access</th><th>Action</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.name)}<div class="ticket-sub">${esc(p.email)}</div></td><td><select data-member-role="${esc(p.id)}" aria-label="Role for ${esc(p.name)}">${options(['technician','dispatcher','manager','admin'],p.role)}</select></td><td>${p.active?'Active':'Deactivated'}</td><td><button data-member="${esc(p.id)}" data-active="${!p.active}">${p.active?'Deactivate':'Reactivate'}</button><button data-save-role="${esc(p.id)}">Save role</button></td></tr>`).join('')}</tbody></table></div>`;
 for(const b of document.querySelectorAll('[data-member],[data-save-role]'))b.onclick=()=>run(async()=>{const id=b.dataset.member||b.dataset.saveRole,p=rows.find(p=>p.id===id),role=document.querySelector(`[data-member-role="${id}"]`).value,active=b.dataset.member?b.dataset.active==='true':p.active;if(!confirm(`Set ${p.name} to ${role}, ${active?'active':'deactivated'}?`))return;await request('/rest/v1/rpc/admin_update_member',{method:'POST',body:{p_id:id,p_role:role,p_active:active}});await loadShared();await loadEnergyMembers();toast('Energy membership updated.')})}
async function checkEnergyMembership(){if(!configured||!session||!profile)return;try{const found=await request('/rest/v1/profiles?select=id,role,active&id=eq.'+encodeURIComponent(profile.id));if(!found.some(p=>p.active)){session=null;profile=null;tickets=[];profiles=[];directory=[];sessionStorage.removeItem('ue-session');document.querySelectorAll('dialog[open]').forEach(d=>d.close());render();toast('Your Energy access is no longer active. Contact the administrator.')}else if(found[0].role!==profile.role){profile.role=found[0].role;document.querySelectorAll('dialog[open]').forEach(d=>d.close());render()}}catch{ /* No success is inferred from a network failure; database rules still enforce access. */ }}
setInterval(checkEnergyMembership,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkEnergyMembership()});

async function loadInvitationQueue(){
 const [queue,releases,members]=await Promise.all([request('/rest/v1/energy_invitation_queue?select=*&order=name'),request('/rest/v1/energy_invitation_release?select=*'),request('/rest/v1/rpc/list_energy_members',{method:'POST',body:{}})]);
 const release=releases[0];const target=$('#invitation-queue');if(!target)return;
 target.innerHTML=`<p><strong>${release?.approved?'Operations approval recorded — ready for release':'ON HOLD — awaiting Operations approval'}</strong></p><p class="section-note">Draft entries have no login permission. Email is the sign-in username. Review every role and include only current Energy staff. Any edit puts the batch back on hold. Original workbook roles and notes remain in Lists.</p><div class="table-wrap"><table><thead><tr><th>Include</th><th>Name / email</th><th>Access role</th><th>Workbook role / notes</th><th>Status</th><th></th></tr></thead><tbody>${queue.map((q,i)=>`<tr><td><input type="checkbox" aria-label="Include ${esc(q.name)}" id="queue-include-${i}" ${q.included?'checked':''} ${q.status==='sent'?'disabled':''}></td><td>${esc(q.name)}<br>${esc(q.email)}</td><td><select id="queue-role-${i}" aria-label="Role for ${esc(q.name)}" ${q.status==='sent'?'disabled':''}>${options(['technician','dispatcher','manager','admin'],q.role)}</select></td><td>${esc(directory.find(d=>d.email.toLowerCase()===q.email)?.source_role||'Manual entry')}<br>${esc(q.notes)}</td><td>${q.status==='sent'?'Sent / approved':q.included?'Pending — on hold':'Excluded — review required'}</td><td>${q.status==='pending'?`<button data-save-queue="${i}">Save review</button>`:''}</td></tr>`).join('')}</tbody></table></div><label>Operations approval reference<input id="operations-reference" placeholder="Approver, approval date and reference" value="${esc(release?.approval_reference||'')}"></label><label><input type="checkbox" id="operations-confirm"> I have received Operations approval and reviewed the included names and roles.</label><button id="release-invitations" class="primary">Record approval & send pending batch</button> <button id="hold-invitations">Keep invitations on hold</button><p id="batch-result" role="status"></p>`;
 target.querySelectorAll('[data-save-queue]').forEach(button=>button.onclick=()=>run(async()=>{const i=Number(button.dataset.saveQueue),q=queue[i];await request('/rest/v1/rpc/energy_stage_invitation',{method:'POST',body:{p_email:q.email,p_name:q.name,p_role:$('#queue-role-'+i).value,p_notes:q.notes,p_included:$('#queue-include-'+i).checked}});await loadInvitationQueue();toast('Review saved. Invitations remain on hold.')}));
 $('#hold-invitations').onclick=()=>run(async()=>{await request('/rest/v1/rpc/energy_set_invitation_release',{method:'POST',body:{p_approved:false,p_reference:''}});await loadInvitationQueue()});
 $('#release-invitations').onclick=()=>run(async()=>{
  if(!$('#operations-confirm').checked)throw Error('Operations approval is required before sending.');
  const reference=$('#operations-reference').value.trim();if(reference.length<5)throw Error('Enter the Operations approval reference.');
  if(queue.some((q,i)=>q.status==='pending'&&(q.included!==$('#queue-include-'+i).checked||q.role!==$('#queue-role-'+i).value)))throw Error('Save your role and inclusion reviews before releasing.');
  const pending=queue.filter(q=>q.included&&q.status==='pending');if(!pending.length)throw Error('No included pending invitations.');
  if(!confirm(`Operations approval: ${reference}\nSend ${pending.length} invitations and approve these accounts now?`))return;
  $('#release-invitations').disabled=true;
  try{await request('/rest/v1/rpc/energy_set_invitation_release',{method:'POST',body:{p_approved:true,p_reference:reference}});
   let sent=0;for(const q of pending){$('#batch-result').textContent=`Processing ${q.name} (${sent+1}/${pending.length})…`;if(members.some(m=>m.email.toLowerCase()===q.email)){await request('/rest/v1/rpc/energy_mark_invitation_sent',{method:'POST',body:{p_email:q.email}})}else{await request('/functions/v1/energy-members',{method:'POST',body:{email:q.email,name:q.name,role:q.role}})}sent++}
   toast(`${sent} invitations processed. Existing approved accounts were skipped.`);
  }finally{await request('/rest/v1/rpc/energy_set_invitation_release',{method:'POST',body:{p_approved:false,p_reference:reference}});await loadInvitationQueue();await loadEnergyMembers()}
 });
}
